const concreteBySlug = new Map(concreteProjects.map((project) => [project.slug, project]));
const bundles = createProjectBundles(concreteBySlug);
const standaloneProjects = concreteProjects.filter(
  (project) => !bundledConcreteSlugs.has(project.slug),
);
const setupProjects = standaloneProjects.filter((project) => project.journey === "setup");
const portfolioProjects = standaloneProjects.filter((project) => project.journey !== "setup");

export const projects: CatalogProject[] = [...setupProjects, ...bundles, ...portfolioProjects];

export const questProjects: ProjectDefinition[] = projects.flatMap((project) =>
  isProjectBundle(project) ? [project.formats.service, project.formats.agent] : [project],
);

/** Сколько проектов в библиотеке без подготовительных уроков: число из каталога, а не из памяти. */
export const libraryProjectCount: number = questProjects.filter((project) => project.journey !== "setup").length;

export function isProjectBundle(project: CatalogProject): project is ProjectBundleDefinition {
  return "formats" in project;
}

export function getProject(slug: string): CatalogProject | undefined {
  return projects.find((project) => project.slug === slug);
}

export function getQuestProject(slug: string): ProjectDefinition | undefined {
  return questProjects.find((project) => project.slug === slug);
}

export function resolveProjectVariant(
  project: CatalogProject,
  format?: ProjectFormat,
): ProjectDefinition | undefined {
  if (!isProjectBundle(project)) return project;
  return format ? project.formats[format] : undefined;
}
